@import "@fontsource-variable/inter/opsz.css";
@import "@fontsource-variable/archivo/wdth.css";

/* Light: the sibling. An off-white page with black ink, the same three accents a step deeper
   so they hold up on white, hairlines in ink at 25%. */
:root {
  --background: oklch(0.961 0 0);
  --foreground: oklch(0 0 0);
  --card: oklch(0.93 0 0);
  --card-foreground: oklch(0 0 0);
  --popover: oklch(0.985 0 0);
  --popover-foreground: oklch(0 0 0);
  --primary: oklch(0.62 0.22 37.4);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.91 0 0);
  --secondary-foreground: oklch(0 0 0);
  --muted: oklch(0.88 0 0);
  --muted-foreground: oklch(0.45 0 0);
  --accent: oklch(0 0 0 / 5%);
  --accent-foreground: oklch(0 0 0);
  --destructive: oklch(0.58 0.22 27);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0 0 0 / 25%);
  --input: oklch(0 0 0 / 30%);
  --ring: oklch(0.62 0.22 37.4);
  --highlight: oklch(0.58 0.23 340.8);
  --highlight-foreground: oklch(1 0 0);
  --glow: oklch(0.6 0.2 301);
  --chart-1: oklch(0.62 0.22 37.4);
  --chart-2: oklch(0.58 0.23 340.8);
  --chart-3: oklch(0.6 0.2 301);
  --chart-4: oklch(0.55 0.12 250);
  --chart-5: oklch(0.45 0 0);
  --sidebar: oklch(0.93 0 0);
  --sidebar-foreground: oklch(0 0 0);
  --sidebar-primary: oklch(0.62 0.22 37.4);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0 0 0 / 5%);
  --sidebar-accent-foreground: oklch(0 0 0);
  --sidebar-border: oklch(0 0 0 / 25%);
  --sidebar-ring: oklch(0.62 0.22 37.4);

  --typeface-body: "Inter Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Archivo Variable", "Inter Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.25rem;
  --page-width: 90rem;
  --page-gutter: 1.25rem;
  --section-y: 2.1875rem;

  /* Theme-only (not tokens): the stokespace blocks read these so their headings set extra
     wide here and at normal width under any other theme. */
  --stokespace-stretch: 125%;
  --stokespace-widen: 0.05em;
}

@media (min-width: 64rem) {
  :root {
    --page-gutter: 0.625rem;
    --section-y: 4.375rem;
  }
}

/* Dark: the faithful mode. Pure black #000, off-white ink #f2f2f2 (muted text is that ink at
   30%, panels at 5%), orange #ff4f00 for hovers and glows, magenta #de3cb3, violet #af73ff. */
.dark {
  --background: oklch(0 0 0);
  --foreground: oklch(0.961 0 0);
  --card: oklch(0.159 0 0);
  --card-foreground: oklch(0.961 0 0);
  --popover: oklch(0.12 0 0);
  --popover-foreground: oklch(0.961 0 0);
  --primary: oklch(0.67 0.222 37.4);
  --primary-foreground: oklch(0 0 0);
  --secondary: oklch(0.218 0 0);
  --secondary-foreground: oklch(0.961 0 0);
  --muted: oklch(0.218 0 0);
  --muted-foreground: oklch(0.62 0 0);
  --accent: oklch(0.961 0 0 / 5%);
  --accent-foreground: oklch(0.961 0 0);
  --destructive: oklch(0.65 0.22 25);
  --destructive-foreground: oklch(0.961 0 0);
  --border: oklch(0.961 0 0 / 30%);
  --input: oklch(0.961 0 0 / 30%);
  --ring: oklch(0.67 0.222 37.4);
  --highlight: oklch(0.634 0.229 340.8);
  --highlight-foreground: oklch(0 0 0);
  --glow: oklch(0.68 0.202 301);
  --chart-1: oklch(0.67 0.222 37.4);
  --chart-2: oklch(0.634 0.229 340.8);
  --chart-3: oklch(0.68 0.202 301);
  --chart-4: oklch(0.62 0.12 250);
  --chart-5: oklch(0.62 0 0);
  --sidebar: oklch(0.12 0 0);
  --sidebar-foreground: oklch(0.961 0 0);
  --sidebar-primary: oklch(0.67 0.222 37.4);
  --sidebar-primary-foreground: oklch(0 0 0);
  --sidebar-accent: oklch(0.961 0 0 / 5%);
  --sidebar-accent-foreground: oklch(0.961 0 0);
  --sidebar-border: oklch(0.961 0 0 / 30%);
  --sidebar-ring: oklch(0.67 0.222 37.4);
}
